from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c]:
                continue
            seen[r][c] = True
            component = [(r, c)]
            for y, x in component:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        component.append((ny, nx))
            if color == bg:
                for y, x in component:
                    out[y][x] = color
            elif len(component) >= 4:
                r0 = min(y for y, x in component)
                r1 = max(y for y, x in component)
                c0 = min(x for y, x in component)
                c1 = max(x for y, x in component)
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color
    return out

